#!/usr/bin/env node
/**
 * Seeds a judge-ready demo workspace into the configured Supabase project.
 *
 * - Creates (or reuses) confirmed accounts, so nobody has to sign up.
 * - Resets the demo brand kit, submissions and findings to a fixed, realistic
 *   set so every re-run gives the same walkthrough.
 *
 *   node scripts/seed-demo.mjs            # write to Supabase
 *   node scripts/seed-demo.mjs --dry-run  # print what would be written
 *
 * Findings are generated by the real rule engine, not written by hand. The
 * audit record re-runs that engine over the same text and reports which stored
 * findings it still reproduces; hand-written messages drifted from the engine's
 * wording and every seeded audit record reported "0 reproduced". Generating
 * them means the demo record reproduces itself.
 *
 * Requires NEXT_PUBLIC_SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY in .env.local.
 * Secrets are read from that file and never printed.
 */
import { readFileSync } from "node:fs";
import { fileURLToPath, pathToFileURL } from "node:url";
import { dirname, join } from "node:path";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const dryRun = process.argv.includes("--dry-run");

function loadEnv() {
  const env = { ...process.env };
  for (const file of [".env.local", ".env"]) {
    try {
      const text = readFileSync(join(root, file), "utf8");
      for (const line of text.split(/\r?\n/)) {
        const match = /^\s*([A-Za-z0-9_]+)\s*=\s*(.*)\s*$/.exec(line);
        if (!match) continue;
        const [, key, raw] = match;
        if (env[key]) continue;
        env[key] = raw.replace(/^["']|["']$/g, "");
      }
    } catch {
      /* optional */
    }
  }
  return env;
}

const env = loadEnv();
const url = env.NEXT_PUBLIC_SUPABASE_URL;
const serviceKey = env.SUPABASE_SERVICE_ROLE_KEY;

if (!dryRun && (!url || !serviceKey)) {
  console.error(
    "Missing NEXT_PUBLIC_SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY in .env.local."
  );
  process.exit(2);
}

