const headers = {
  apikey: serviceKey,
  Authorization: `Bearer ${serviceKey}`,
  "Content-Type": "application/json",
};

async function call(path, init = {}) {
  const res = await fetch(`${url}${path}`, {
    ...init,
    headers: { ...headers, ...(init.headers ?? {}) },
  });
  const text = await res.text();
  let body = null;
  if (text) {
    try {
      body = JSON.parse(text);
    } catch {
      body = text;
    }
  }
  if (!res.ok) {
    const error = new Error(`${init.method ?? "GET"} ${path} → ${res.status}: ${text}`);
    error.status = res.status;
    error.body = text;
    throw error;
  }
  return body;
}

async function findUserIdByEmail(email) {
  for (let page = 1; page <= 20; page += 1) {
    const data = await call(`/auth/v1/admin/users?page=${page}&per_page=200`);
    const users = data?.users ?? [];
    const hit = users.find((u) => u.email?.toLowerCase() === email.toLowerCase());
    if (hit) return hit.id;
    if (users.length < 200) return null;
  }
  return null;
}

async function ensureUser({ email, password, name, role }, org) {
  let id;
  try {
    const created = await call("/auth/v1/admin/users", {
      method: "POST",
      body: JSON.stringify({
        email,
        password,
        email_confirm: true,
        user_metadata: { full_name: name },
      }),
    });
    id = created.id;
    console.log(`created ${email}`);
  } catch (error) {
    id = await findUserIdByEmail(email);
    if (!id) throw error;
    console.log(`reused ${email}`);
  }

  await call("/rest/v1/profiles?on_conflict=id", {
    method: "POST",
    headers: { Prefer: "resolution=merge-duplicates,return=minimal" },
    body: JSON.stringify({ id, role, organization: org }),
  });
  return id;
}

