/** Bundle the app's own engine, so seeded findings are what it produces. */
async function loadEngine() {
  const { build } = await import("esbuild");
  const bundlePath = join(root, ".build/seed-engine.mjs");
  await build({
    stdin: {
      contents: [
        'export { runRuleSet } from "./src/lib/rules.ts";',
        'export { stripAnchors } from "./src/lib/document-extract.ts";',
        'export { buildAuditPack } from "./src/lib/audit-pack.ts";',
      ].join("\n"),
      resolveDir: root,
      loader: "ts",
    },
    bundle: true,
    format: "esm",
    platform: "node",
    outfile: bundlePath,
    logLevel: "warning",
  });
  return import(pathToFileURL(bundlePath).href);
}

/** Which decision, if any, this reviewer already recorded for a finding. */
function decisionFor(decisions, finding, used) {
  for (const decision of decisions) {
    if (used.has(decision) || decision.ruleId !== finding.ruleId) continue;
    if (
      decision.match &&
      !finding.message.toLowerCase().includes(decision.match.toLowerCase())
    ) {
      continue;
    }
    used.add(decision);
    return decision.status;
  }
  return "pending";
}

/** Findings for one submission, straight from the deterministic engine. */
function findingsFor(engine, submission, submissionId) {
  const text = engine.stripAnchors(submission.text_content);
  const run = engine.runRuleSet(text, kit, { submissionId });
  const decisions = submission.decisions ?? [];
  const used = new Set();
  return run.findings.map((finding) => ({
    submission_id: submissionId,
    type: finding.type,
    severity: finding.severity,
    message: finding.message,
    citation: finding.citation,
    source_passage: finding.sourcePassage ?? null,
    suggestion: finding.suggestion ?? null,
    rule_id: finding.ruleId,
    status: decisionFor(decisions, finding, used),
    created_at: submission.created_at,
    updated_at: submission.created_at,
  }));
}

/**
 * `rule_id` arrives with migration 0004. Write it when the column exists and
 * fall back to the fields that have always worked, so seeding never depends on
 * a migration the owner has not applied yet.
 */
async function insertFindings(rows) {
  try {
    await call("/rest/v1/findings", {
      method: "POST",
      headers: { Prefer: "return=minimal" },
      body: JSON.stringify(rows),
    });
  } catch (error) {
    const missingColumn =
      error.status === 400 && /42703|PGRST204|column .* does not exist/i.test(error.body ?? "");
    if (!missingColumn) throw error;
    const withoutRule = rows.map((row) => {
      const copy = { ...row };
      delete copy.rule_id;
      return copy;
    });
    await call("/rest/v1/findings", {
      method: "POST",
      headers: { Prefer: "return=minimal" },
      body: JSON.stringify(withoutRule),
    });
    return "without rule_id (migration 0004 not applied)";
  }
  return "with rule_id";
}

async function seed() {
  const engine = await loadEngine();

  // Work out every finding up front: a dry run needs no database at all, and a
  // real run fails before touching data if the engine cannot read something.
  const planned = submissions.map((submission) => ({
    submission,
    findings: findingsFor(engine, submission, `dry-${submission.key}`),
  }));

  if (dryRun) {
    let total = 0;
    for (const { submission, findings } of planned) {
      total += findings.length;
      console.log(`\n${submission.status.padEnd(12)} ${submission.title} (${findings.length})`);
      for (const finding of findings) {
        console.log(
          `  ${finding.severity.padEnd(8)} ${finding.rule_id.padEnd(26)} ${finding.status}`
        );
        console.log(`           ${finding.message}`);
      }
      // The audit record re-runs the engine and names what it cannot reproduce,
      // so the seed can prove the same thing before writing anything.
      const pack = engine.buildAuditPack({
        submission: {
          id: `dry-${submission.key}`,
          brand_kit_id: kit.id,
          title: submission.title,
          content_type: submission.content_type ?? "text",
          status: submission.status,
          text_content: submission.text_content,
          created_at: submission.created_at,
        },
        findings: findings.map((finding, index) => ({
          ...finding,
          id: `dry-${submission.key}-${index}`,
        })),
        kit,
        generatedAt: submission.created_at,
      });
      console.log(
        `  audit record: ${pack.reconciliation.reproduced} of ${pack.reconciliation.total} reproduced, ${pack.reconciliation.engineOnly.length} extra`
      );
      if (pack.reconciliation.reproduced !== pack.reconciliation.total) {
        throw new Error(`${submission.title} would not reproduce its own record.`);
      }
    }
    console.log(`\nDry run: ${planned.length} submissions, ${total} findings. Nothing written.`);
    return;
  }

  console.log(`Seeding ${ORG} demo workspace → ${url}`);

  const judgeId = await ensureUser(DEMO_ACCOUNT, ORG);
  for (const member of TEAM) await ensureUser(member, ORG);

  // Reset the demo workspace: deleting the kit cascades to submissions and findings.
  await call(`/rest/v1/brand_kits?organization_id=eq.${judgeId}`, {
    method: "DELETE",
    headers: { Prefer: "return=minimal" },
  });

  const [kitRow] = await call("/rest/v1/brand_kits?select=id", {
    method: "POST",
    headers: { Prefer: "return=representation" },
    body: JSON.stringify({
      name: ORG,
      organization_id: judgeId,
      guidelines,
      glossary,
      facts,
      palette,
      logo_url: LOGO_URL,
      created_at: ago(74),
      updated_at: ago(3),
    }),
  });

  let findingCount = 0;
  for (const { submission } of planned) {
    const [row] = await call("/rest/v1/content_submissions?select=id", {
      method: "POST",
      headers: { Prefer: "return=representation" },
      body: JSON.stringify({
        brand_kit_id: kitRow.id,
        title: submission.title,
        content_type: submission.content_type ?? "text",
        status: submission.status,
        text_content: submission.text_content,
        image_url: submission.image_url ?? null,
        created_at: submission.created_at,
        updated_at: submission.created_at,
      }),
    });

    const findings = findingsFor(engine, submission, row.id);
    const writeKind = findings.length > 0 ? await insertFindings(findings) : "none";
    findingCount += findings.length;
    console.log(
      `  ${submission.status.padEnd(12)} ${submission.title} — ${findings.length} findings (${writeKind})`
    );
  }

  console.log(
    `\nDone. ${submissions.length} submissions, ${findingCount} findings, 1 brand kit.`
  );
  console.log(`Demo sign-in: ${DEMO_ACCOUNT.email} / ${DEMO_ACCOUNT.password}`);
}

seed().catch((error) => {
  console.error("\nSeed failed:", error.message);
  process.exit(1);
});
